import React, { useState } from "react";
import { BrowserRouter as Router, Route, Routes } from "react-router-dom";
import Header from "./components/Header";
import Footer from "./components/Footer";
import DiceGame from "./components/DiceGame";
import SessionForm from "./components/SessionForm";
import Login from "./components/Login";
import ScorePage from "./components/ScorePage"; // Importez le composant ScorePage
import "bootstrap/dist/css/bootstrap.min.css";
// import ".src//App.css";

function App() {
  const [playerName, setPlayerName] = useState(null);
  const handleLogin = (name) => {
    setPlayerName(name);
  };
  return (
    <Router>
      <div className="App">
        <Header playerName={playerName} />
        <main>
          <Routes>
            <Route path="/" element={<Accueil />} />
            <Route path="/login" element={<Login onLogin={handleLogin} />} />
            <Route
              path="/start-game"
              element={<DiceGame playerName={playerName} />}
            />
            <Route
              path="/with-config"
              element={<SessionForm playerName={playerName} />}
            />
            <Route path="/score" element={<ScorePage />} />
          </Routes>
        </main>
        <Footer />
      </div>
    </Router>
  );
}

const Accueil = () => {
  return (
    <div className="welcome-container">
      <h2 className="welcome-title">Welcome to Dice Game</h2>
      <p className="welcome-text">
        Nous sommes ravis de vous présenter notre nouveau jeu de dés. Bien qu'il
        existe de nombreux jeux de dés disponibles, nous travaillons dur pour
        rendre le nôtre unique. Nous prévoyons d'intégrer l'IA pour améliorer le
        gameplay, et nous explorons également l'utilisation du rendu 3D pour
        apporter un nouveau niveau d'immersion au jeu. Restez à l'écoute des
        mises à jour et préparez-vous à vivre une expérience de jeu passionnante
        ! Veuillez vous connecter pour jouer au jeu.
      </p>
      <p className="welcome-text">Please login to play the game.</p>
    </div>
  );
};

export default App;
